#pragma once
// Palette entries for the strand hair nodes (docs/plans/wave11/SOFTBODY_HAIR.md 2.20). NOT standalone: GraphNodeFamilies.gen.inc (generated by
// cmake/GraphNodeFamilies.cmake) includes it from GraphNodeDefs.hpp inside namespace aver::editor::detail, after pin()/attr() are
// defined, and calls appendHairNodeDefs(t).
//
// MIRRORS scripting/csharp/Aver.Graph/GraphHairNodeTable.cs pin for pin. A hair is the entity id (0 = none) of the character that carries the
// CHair component, never a Jolt handle. The groom (Add Hair), the look material (Set Hair Look) and the collider bone (Add Hair Collider) are
// node attributes, not pins. Set Hair Params takes four scales, 1 = the groom's own; a value below 0 leaves that scale alone. Add Hair Collider's
// shape is 0 sphere (sx radius), 1 capsule (sx radius, sy half height) or 2 box (half extents), in centimetres in the owner's space. Set Hair Wind is
// the shared world wind (the soft bodies'), so cloth, ropes and hair move together.

inline void appendHairNodeDefs(std::vector<GraphNodeDesc>& t) {
    t.push_back({"AddHair", "Add Hair", "Physics", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("then", "exec", true), pin("success", "bool", true)},
        {attr("asset", "Groom (.ochair)")}});
    t.push_back({"SetHairParams", "Set Hair Params", "Physics", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("width", "float", false, "1"), pin("density", "float", false, "1"),
        pin("stiffness", "float", false, "1"), pin("wind", "float", false, "1"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"SetHairLook", "Set Hair Look", "Physics", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("then", "exec", true), pin("success", "bool", true)},
        {attr("material", "Look material (.ocmat with the hair shading model)")}});
    t.push_back({"SetHairEnabled", "Set Hair Enabled", "Physics", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("on", "bool", false, "true"),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"TeleportHair", "Teleport Hair", "Physics", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"AddHairCollider", "Add Hair Collider", "Physics", {
        pin("exec", "exec", false), pin("entity", "int", false), pin("shape", "int", false, "0"), pin("sx", "float", false, "10"),
        pin("sy", "float", false, "0"), pin("sz", "float", false, "0"),
        pin("then", "exec", true), pin("success", "bool", true)},
        {attr("bone", "Bone the collider follows")}});
    t.push_back({"GetHair", "Get Hair", "Physics", {
        pin("entity", "int", false), pin("found", "bool", true), pin("simulating", "bool", true), pin("lod", "int", true),
        pin("renderStrands", "int", true), pin("simStrands", "int", true)}});
    t.push_back({"SetHairWind", "Set Hair Wind", "Physics", {
        pin("exec", "exec", false), pin("x", "float", false), pin("y", "float", false), pin("z", "float", false), pin("gust", "float", false, "0"),
        pin("then", "exec", true), pin("success", "bool", true)}});
}
